  Object.assign(names,{whatsapp_flows:'Fluxos WhatsApp',orders_online:'Pedidos Online',sales_history:'Histórico Vendas',products:'Produtos',categories:'Categorias',delivery:'Configuração de Entrega',hours:'Horários',store_share:'Compartilhar Loja',google_business:'Google Meu Negócio',files:'Arquivos',payments:'Pagamentos',store_editor:'Editor da Loja'});
  Object.assign(icons,{whatsapp_flows:'↯',orders_online:'▣',sales_history:'▤',products:'▦',categories:'⌘',delivery:'⌁',hours:'◷',store_share:'↗',google_business:'G',files:'▱',payments:'$',store_editor:'▤'});

  const proSaveSettings=async values=>{await api('/api/settings',{method:'POST',body:JSON.stringify(values)});toast('Configurações salvas');};
  const proToggle=(name,label,checked)=>`<label class="pro-switch-row"><span><b>${label}</b><small>Ativar esta opção no atendimento</small></span><input type="checkbox" name="${name}" ${checked?'checked':''}><i></i></label>`;
  const proSettingInput=(name,label,value,type='text',hint='')=>`<label class="pro-setting-field"><span>${label}</span><input class="input" name="${name}" type="${type}" value="${esc(value||'')}" placeholder="${hint}"></label>`;
  const proSection=(title,desc,body,action='')=>`<section class="pro-settings-section"><div class="pro-settings-title"><div><h2>${title}</h2><p>${desc}</p></div>${action}</div>${body}</section>`;

  pages.settings=async()=>{const s=await proSettings();const waProvider=s.whatsapp_provider||'evolution';$('#content').innerHTML=proHeader('Configurações','Conexões, automações, horários e identidade do KV CELL OS PRO','<span class="pro-live-dot">● SISTEMA ONLINE</span>')+`<div class="pro-settings-layout"><aside class="pro-settings-menu"><b>CONFIGURAÇÕES</b><button class="active">▣ WhatsApp Automático</button><button>◉ PDV / Caixa</button><button>⌁ Entrega</button><button>◷ Horários</button><button>◎ Financeiro</button><button>⚙ Geral</button><button>▤ Integrações</button><button>▣ Inteligência Artificial</button></aside><div class="pro-settings-body"><form id="proSettingsForm">${proSection('WhatsApp Automático','Configure o provedor que o sistema usará para enviar e receber mensagens.',`<div class="pro-connection-head"><div><b>Ativar integração</b><small>Use o WhatsApp para avisos de OS, orçamentos e pedidos.</small></div><input type="checkbox" name="whatsapp_enabled" ${s.whatsapp_enabled!=='false'?'checked':''}></div><div class="pro-provider-grid"><label><input type="radio" name="whatsapp_provider" value="2api" ${waProvider==='2api'?'checked':''}><b>2-API</b><small>API oficial / gateway</small></label><label><input type="radio" name="whatsapp_provider" value="evolution" ${waProvider==='evolution'?'checked':''}><b>Evolution API</b><small>Servidor próprio</small></label><label><input type="radio" name="whatsapp_provider" value="integrated" ${waProvider==='integrated'?'checked':''}><b>WhatsApp Integrado</b><small>Conexão por QR Code</small></label></div><div class="pro-settings-grid">${proSettingInput('whatsapp_base_url','URL da API',s.whatsapp_base_url||'','url','https://api.exemplo.com')}${proSettingInput('whatsapp_instance','Instância / conexão',s.whatsapp_instance||'','text','kv-cell')}${proSettingInput('whatsapp_token','Token da API',s.whatsapp_token||'','password','Token secreto')}${proSettingInput('whatsapp_phone','Número do WhatsApp',s.whatsapp_phone||s.phone||'','tel','552198...')}${proSettingInput('whatsapp_test_phone','Telefone de teste',s.whatsapp_test_phone||'','tel','552198...')}</div><div class="pro-settings-actions"><button class="btn pro-btn" type="button" onclick="go('linking')">Gerar QR / Conectar</button><button class="btn yellow-btn" type="submit">Salvar Configurações</button></div>`)}${proSection('Automações por evento','Escolha quando enviar mensagens automáticas para o cliente.',`<div class="pro-automation-list">${proToggle('wa_new_client','Novo cliente',s.wa_new_client!=='false')}${proToggle('wa_new_os','Nova ordem de serviço',s.wa_new_os!=='false')}${proToggle('wa_quote','Orçamento criado',s.wa_quote!=='false')}${proToggle('wa_ready','Aparelho pronto',s.wa_ready!=='false')}${proToggle('wa_delivered','OS entregue',s.wa_delivered!=='false')}${proToggle('wa_cancelled','OS cancelada',s.wa_cancelled!=='false')}</div><button class="btn yellow-btn" type="button" onclick="go('whatsapp_flows')">Abrir editor de Fluxos WhatsApp</button>`)}${proSection('Templates de Status','Mensagens editáveis usadas nos eventos da OS.',`<div class="pro-template-list"><label><span>Pronto</span><textarea class="textarea" name="wa_template_ready">${esc(s.wa_template_ready||'Olá {cliente}! Sua OS #{os} está pronta para retirada na KV CELL.')}</textarea></label><label><span>Em andamento</span><textarea class="textarea" name="wa_template_progress">${esc(s.wa_template_progress||'Olá {cliente}! Sua OS #{os} está em andamento na bancada.')}</textarea></label><label><span>Entregue</span><textarea class="textarea" name="wa_template_delivered">${esc(s.wa_template_delivered||'Obrigado pela preferência, {cliente}! A OS #{os} foi entregue.')}</textarea></label></div>`)}${proSection('Instagram e Catálogo','Perfil social, publicação e divulgação pública.',`<div class="pro-settings-grid">${proSettingInput('instagram','@ do Instagram',s.instagram||'','text','@kvcell')}${proSettingInput('instagram_access_token','Token do Instagram',s.instagram_access_token||'','password','Token comercial')}${proSettingInput('catalog_slug','Slug do catálogo',s.catalog_slug||'kvcell','text','kvcell')}${proSettingInput('catalog_title','Título do catálogo',s.catalog_title||'KV CELL','text','Minha loja')}${proSettingInput('catalog_whatsapp','WhatsApp do catálogo',s.catalog_whatsapp||s.phone||'','tel','552198...')}</div>`)}${proSection('Identidade da loja','Dados exibidos no painel e no catálogo público.',`<div class="pro-settings-grid">${proSettingInput('company_name','Nome da empresa',s.company_name||'KV CELL OS PRO')}${proSettingInput('tagline','Subtítulo',s.tagline||'Assistência técnica e acessórios')}${proSettingInput('phone','Telefone',s.phone||'','tel')}${proSettingInput('units','Unidades',s.units||'LAGOS,MAGÉ')}</div>`)}</form></div></div>`;$('#proSettingsForm').onsubmit=async e=>{e.preventDefault();const data=formValues(e.target);data.whatsapp_enabled=String(Boolean(e.target.whatsapp_enabled?.checked));['wa_new_client','wa_new_os','wa_quote','wa_ready','wa_delivered','wa_cancelled'].forEach(k=>data[k]=String(Boolean(e.target[k]?.checked)));await proSaveSettings(data)} };

  const flowBlocks=[['Receber mensagem','Quando uma nova conversa chegar'],['Menu','Mostra opções para o cliente'],['Texto','Envia uma mensagem personalizada'],['Mídia','Envia foto, vídeo ou documento'],['Aguardar','Espera a resposta do cliente'],['Condição','Divide o fluxo por resposta'],['Conectar O.S.','Consulta status da ordem'],['Buscar cliente','Localiza cadastro pelo telefone'],['Criar atendimento','Abre uma nova OS'],['Transferir','Passa para a equipe'],['Encerrar','Finaliza o atendimento']];
  window.proFlowAdd=function(label){const canvas=document.querySelector('#proFlowCanvas');if(!canvas)return;const node=document.createElement('div');node.className='pro-flow-node';node.innerHTML=`<b>${esc(label)}</b><small>Bloco configurável</small><button onclick="this.parentElement.remove()">×</button>`;canvas.appendChild(node)};
  pages.whatsapp_flows=async()=>{const savedFlows=JSON.parse(localStorage.getItem('kv_pro_flows')||'[]');$('#content').innerHTML=proHeader('Fluxos WhatsApp','Monte automações visuais para responder clientes e ligar o atendimento às OS.',`<button class="btn yellow-btn" onclick="proFlowAdd('Novo bloco')">+ Novo bloco</button>`)+`<div class="pro-flow-builder"><aside class="pro-flow-library"><b>FLOW BUILDER</b><small>Arraste blocos para o fluxo</small>${flowBlocks.map(x=>`<button onclick="proFlowAdd('${esc(x[0])}')"><strong>${esc(x[0])}</strong><small>${esc(x[1])}</small></button>`).join('')}</aside><section class="pro-flow-workspace"><div class="pro-flow-toolbar"><span>Fluxo de atendimento <b class="badge g">ATIVO</b></span><div><button class="btn ghost" onclick="toast('Fluxo testado com sucesso')">▶ Testar</button><button class="btn yellow-btn" onclick="localStorage.setItem('kv_pro_flows',JSON.stringify([...document.querySelectorAll('#proFlowCanvas .pro-flow-node b')].map(x=>x.textContent)));toast('Fluxo salvo')">Salvar</button></div></div><div id="proFlowCanvas" class="pro-flow-canvas"><div class="pro-flow-start">Receber mensagem</div>${savedFlows.map(x=>`<div class="pro-flow-node"><b>${esc(x)}</b><small>Bloco salvo</small><button onclick="this.parentElement.remove()">×</button></div>`).join('')}<div class="pro-flow-end">Encerrar conversa</div></div></section><aside class="pro-flow-inspector"><b>INSPECTOR</b><label>Selecionar bloco<select class="select"><option>Mensagem inicial</option><option>Menu principal</option><option>Status da OS</option></select></label><label>Conteúdo<textarea class="textarea" placeholder="Digite a mensagem..."></textarea></label><button class="btn yellow-btn">Aplicar bloco</button></aside></div>`};

  pages.instagram=async()=>{const s=await proSettings();const posts=JSON.parse(localStorage.getItem('kv_ig_posts')||'[]');$('#content').innerHTML=proHeader('Instagram','Conecte o perfil comercial, agende publicações e acompanhe a presença digital.',`<button class="btn yellow-btn" onclick="proInstagramPost()">+ Nova publicação</button>`)+`<div class="pro-social-grid"><section class="pro-social-card instagram-card"><div class="pro-social-icon">◎</div><div><h2>${esc(s.instagram||'Instagram não conectado')}</h2><p>Perfil comercial da loja</p></div><span class="pro-status ${s.instagram?'online':'offline'}"><i></i>${s.instagram?'Conectado':'Não conectado'}</span><button class="btn yellow-btn" onclick="go('settings')">${s.instagram?'Editar conexão':'Conectar Instagram'}</button></section><section class="pro-social-card"><h2>Publicação rápida</h2><p>Crie uma legenda, anexe a imagem e escolha quando publicar.</p><button class="btn ghost" onclick="proInstagramPost()">Abrir editor</button><button class="btn ghost" onclick="go('catalog')">Divulgar produto do catálogo</button></section></div><section class="pro-settings-section"><div class="pro-settings-title"><div><h2>Planejador de conteúdo</h2><p>Publicações programadas e histórico recente.</p></div><button class="btn ghost" onclick="proInstagramPost()">Atualizar</button></div>${posts.length?`<div class="pro-post-list">${posts.map((p,i)=>`<article><div class="pro-post-image">${p.image?`<img src="${esc(p.image)}">`:'◎'}</div><div><b>${esc(p.title||'Publicação Instagram')}</b><p>${esc(p.caption||'')}</p><small>${esc(p.date||'Agendada')} • ${esc(p.status||'Rascunho')}</small></div><button class="btn ghost" onclick="navigator.clipboard?.writeText('${esc(p.caption||'')}');toast('Legenda copiada')">Copiar</button></article>`).join('')}`:'<div class="pro-empty">Nenhuma publicação foi cadastrada.</div>'}</section>`};
