  pages.delivery=async()=>{$('#content').innerHTML=proHeader('Configuração de Entrega','Defina zonas de entrega, endereço da loja e cálculo de frete.',`<button class="btn yellow-btn" onclick="toast('Configurações de entrega salvas')">Salvar</button>`)+`<section class="pro-settings-section"><div class="pro-connection-head"><div><h2>Configuração de Entrega</h2><p>Defina zonas de raio em torno da sua loja com valores de frete automáticos.</p></div><input type="checkbox"></div><div class="pro-settings-grid">${proSettingInput('store_postal_code','CEP','','text','00000-000')}${proSettingInput('store_address','Endereço / Bairro / Cidade','','text','Rua, Cidade, Bairro...')}</div><div class="pro-delivery-map"><div class="pro-map-fallback">Mapa de zonas de entrega • arraste o pino da loja ou selecione uma zona para testar</div></div><button class="btn yellow-btn full-btn" onclick="toast('Configurações de entrega salvas')">Salvar Configurações de Entrega</button></section>`};
