  pages.store_share=async()=>{const s=await proSettings(),slug=s.catalog_slug||'kvcell',url=location.origin+'/catalog/'+encodeURIComponent(slug);$('#content').innerHTML=proHeader('Compartilhar Loja','Envie seu catálogo para clientes e divulgue em todos os canais.',`<button class="btn ghost" onclick="go('catalog')">Voltar ao catálogo</button>`)+`<section class="pro-share-vertical"><h2>Endereço personalizado</h2><p>Seu link público da loja</p><div class="pro-share-link"><input class="input" readonly value="${esc(url)}"><button class="btn yellow-btn" onclick="navigator.clipboard?.writeText('${esc(url)}');toast('Link copiado')">Copiar</button></div><button class="btn pro-whatsapp-btn full-btn" onclick="window.open('https://wa.me/?text='+encodeURIComponent('Confira nosso catálogo: '+location.origin+'/catalog/${encodeURIComponent(slug)}'),'_blank')">Compartilhar com cliente</button><div class="pro-share-buttons"><a class="btn ghost" target="_blank" href="${esc(url)}">Abrir</a><a class="btn pro-whatsapp-btn" target="_blank" href="https://wa.me/?text=${encodeURIComponent('Confira nosso catálogo: '+url)}">WhatsApp</a></div><div class="pro-qr-placeholder">QR<br><small>Use o link acima para gerar o QR da sua divulgação</small></div></section>`};
