  function proRebuildNav(){const el=document.querySelector('.adapti-sidebar .nav');if(!el)return;const groups=[['VISÃO GERAL',['dashboard','team','reports','finance']],['MAIS USADOS',['pdv','orders_online','quotes','sales_history']],['CLIENTES',['instagram','whatsapp_flows','wa_status','customers']],['SERVIÇOS',['services','diagnostics','quotes','guarantees','fiado','pricing']],['ESTOQUE',['inventory','products','categories','stock_count','stock_moves','suppliers']],['FINANCEIRO',['invoices','charges','finance']],['LOJA ONLINE',['catalog','store_share','google_business']],['LOGÍSTICA',['delivery','hours']],['ADMINISTRAÇÃO',['files','settings','admin']]];el.innerHTML=groups.map(([title,items])=>`<div class="navtitle">${title}</div>${items.filter((x,i,a)=>a.indexOf(x)===i).map(nav).join('')}`).join('');el.querySelector('#nav-'+MOD)?.classList.add('active')}
