  const mapCache=JSON.parse(localStorage.getItem('kv_map_geocodes')||'{}');
  const cleanAddress=x=>[x.address,x.neighborhood,x.city,x.postal_code,'Brasil'].filter(Boolean).join(', ');
  async function coordinates(x){if(x.latitude&&x.longitude)return[Number(x.latitude),Number(x.longitude)];const query=cleanAddress(x)||x.city||'';const key=query.toLowerCase();if(mapCache[key])return mapCache[key];const city=String(x.city||'').toLowerCase();const near=fallback.find(y=>city.includes(y[2].toLowerCase()));if(!query||query==='Brasil'){return near?[near[0],near[1]]:fallback[0].slice(0,2)}try{const res=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=br&q='+encodeURIComponent(query),{headers:{'Accept-Language':'pt-BR'}});const data=await res.json();if(data[0]){const point=[Number(data[0].lat),Number(data[0].lon)];mapCache[key]=point;localStorage.setItem('kv_map_geocodes',JSON.stringify(mapCache));return point}}catch{}return near?[near[0],near[1]]:fallback[0].slice(0,2)}
