  window.supplierForm=function(){formModal('Novo Fornecedor',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${f('name','Nome / Empresa *')}${f('document','CPF / CNPJ')}${f('phone','Telefone')}${f('email','E-mail','email')}${f('address','Rua e número')}${f('neighborhood','Bairro')}${f('postal_code','CEP')}${f('city','Cidade')}${f('notes','Observações','textarea','',true)}</div>`,async()=>{const d=formValues($('#modalForm'));await api('/api/suppliers',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Fornecedor cadastrado com endereço');render()})};
