(function(){
  const oldSettings=pages.settings;
  window.proSettingsJump=function(tab,button){
    const routes={pdv:'pdv',delivery:'delivery',hours:'hours',finance:'finance',integrations:'linking',ai:'ai'};
    document.querySelectorAll('.pro-settings-menu button').forEach(item=>item.classList.remove('active'));
    if(button)button.classList.add('active');
    if(tab==='whatsapp'){document.querySelector('.pro-settings-body')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(tab==='general'){const sections=document.querySelectorAll('.pro-settings-section');sections[sections.length-1]?.scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(routes[tab])go(routes[tab]);
  };
  pages.settings=async function(){
    await oldSettings();
    const buttons=document.querySelectorAll('.pro-settings-menu button');
    const tabs=['whatsapp','pdv','delivery','hours','finance','general','integrations','ai'];
    buttons.forEach((button,index)=>button.onclick=()=>proSettingsJump(tabs[index],button));
  };
})();

