(function(){
  const catalogCategories=products=>{const saved=JSON.parse(localStorage.getItem('kv_catalog_categories')||'[]');return [...new Set([...saved,...products.map(x=>String(x.category||'').trim()).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'pt-BR'))};
  const catalogTabs=tab=>`<div class="pro-catalog-tabs"><button class="btn ${tab==='products'?'yellow-btn':'ghost'}" onclick="proCatalogTab('products')">Produtos</button><button class="btn ${tab==='categories'?'yellow-btn':'ghost'}" onclick="proCatalogTab('categories')">Categorias</button></div>`;
  window.proCatalogTab=function(tab){window.__proCatalogTab=tab;render()};
  window.proCatalogAddCategory=function(){const input=document.querySelector('#newCatalogCategory'),name=String(input?.value||'').trim();if(!name)return toast('Digite o nome da categoria','error');const saved=JSON.parse(localStorage.getItem('kv_catalog_categories')||'[]');if(!saved.includes(name))saved.push(name);localStorage.setItem('kv_catalog_categories',JSON.stringify(saved));toast('Categoria adicionada');render()};
  pages.catalog=async()=>{const [products,s]=await Promise.all([api('/api/catalog-products?unit=TODOS'),proSettings()]);const slug=s.catalog_slug||'kvcell',url='https://kvcell.squareweb.app/catalog/'+encodeURIComponent(slug),categories=catalogCategories(products),tab=window.__proCatalogTab||'products';const productRows=products.filter(x=>{const q=String($('#catalogProductSearch')?.value||'').toLowerCase(),cat=$('#catalogProductCategory')?.value||'';return(!q||String(x.name||'').toLowerCase().includes(q)||String(x.category||'').toLowerCase().includes(q))&&(!cat||x.category===cat)});
    const content=tab==='categories'?`<section class="panel"><div class="pro-catalog-category-add"><input id="newCatalogCategory" class="input" placeholder="Nova categoria"><button class="btn yellow-btn" onclick="proCatalogAddCategory()">Adicionar categoria</button></div><div class="pro-catalog-category-grid">${categories.map(cat=>`<article class="pro-catalog-category-card"><b>${esc(cat)}</b><span>${products.filter(x=>x.category===cat).length} produto(s)</span><button class="btn ghost" onclick="proCatalogTab('products');setTimeout(()=>{const s=document.querySelector('#catalogProductCategory');if(s){s.value='${esc(cat)}';s.dispatchEvent(new Event('change'))}},50)">Ver produtos</button></article>`).join('')||'<div class="pro-empty">Nenhuma categoria cadastrada. Adicione uma categoria acima ou informe-a ao criar um produto.</div>'}</div></section>`:`<section class="panel"><div class="pro-catalog-toolbar"><input id="catalogProductSearch" class="input" placeholder="Buscar produto" oninput="proCatalogRefreshRows()"><select id="catalogProductCategory" class="select" onchange="proCatalogRefreshRows()"><option value="">Todas as categorias</option>${categories.map(x=>`<option>${esc(x)}</option>`).join('')}</select><span>${products.length} produto(s)</span></div><div id="proCatalogProducts" class="pro-catalog-admin-grid">${productRows.map(x=>`<article class="pro-catalog-admin-card"><div class="pro-catalog-admin-image">${x.image?`<img src="${esc(x.image)}" alt="${esc(x.name||'Produto')}">`:'<span>KV</span>'}</div><div class="pro-catalog-admin-body"><span class="pro-kicker">${esc(x.category||'Sem categoria')}</span><h3>${esc(x.name||'Produto')}</h3><b>${money(x.price)}</b><small>Estoque: ${esc(x.stock||0)} • ${x.active?'Publicado':'Oculto'}</small><div class="pro-catalog-admin-actions"><button class="btn yellow-btn" onclick="proCatalogEdit(${x.id})">Editar 100%</button><button class="btn ghost" onclick="api('/api/catalog-products',{method:'PUT',body:JSON.stringify({id:${x.id},active:${x.active?0:1}})}).then(()=>{toast('${x.active?'Produto ocultado':'Produto publicado'}');render()})">${x.active?'Ocultar':'Publicar'}</button><button class="btn danger" onclick="deleteResource('catalog-products',${x.id})">Excluir</button></div></div></article>`).join('')||'<div class="pro-empty">Nenhum produto encontrado.</div>'}</div></section>`;
    $('#content').innerHTML=head('Catálogo Digital','Edite produtos e categorias dentro da sua vitrine.',`<button class="btn yellow-btn" onclick="proCatalogNew()">＋ Adicionar produto</button>`)+`<section class="pro-catalog-editor-head"><div><span class="pro-kicker">EDITOR COMPLETO</span><h2>${esc(s.catalog_title||'KV CELL OS PRO')}</h2><p>${esc(s.catalog_message||'Configure sua vitrine para os clientes.')}</p></div><div class="pro-catalog-public-link"><input class="input" readonly value="${url}"><button class="btn yellow-btn" onclick="navigator.clipboard?.writeText('${url}');toast('Link oficial copiado')">Copiar link</button><a class="btn ghost" target="_blank" href="${url}">Abrir catálogo público</a></div></section>${catalogTabs(tab)}${content}`;
  };
  window.proCatalogRefreshRows=function(){const search=String($('#catalogProductSearch')?.value||'').toLowerCase(),cat=$('#catalogProductCategory')?.value||'';document.querySelectorAll('#proCatalogProducts .pro-catalog-admin-card').forEach(card=>{card.hidden=Boolean(search||cat)&&!card.textContent.toLowerCase().includes(search)&&(!cat||!card.textContent.includes(cat))})};
  const removeConference=()=>{document.querySelectorAll('.adapti-sidebar .nav button').forEach(button=>{const text=(button.textContent||'').toLowerCase();if(text.includes('conferência')||text.includes('categorias'))button.remove()})};
  const oldBoot=boot;boot=async function(){await oldBoot();removeConference()};setTimeout(removeConference,500);
})();
